BASE="$HOME/tcp-incident"
mkdir -p "$BASE/reports"

PORT=$(grep -E '^[[:space:]]*PORT=' "$BASE/config/api.env" 2>/dev/null | cut -d= -f2 | tr -d '[:space:]"' || echo 18202)

# Pre-seeded deterministic incident fixture representing completed Task 1 triage
cat << EOF > "$BASE/reports/queue-triage.env"
# Deterministic incident fixture generated by skip-ahead setup (not a live measurement)
SERVICE_PORT=${PORT:-18202}
CONFIGURED_BACKLOG=5
OBSERVED_SEND_Q=5
OBSERVED_RECV_Q=6
QUEUE_TYPE=ACCEPT_QUEUE
EOF

rm -f "$BASE/reports/metric-drops.env" "$BASE/reports/verification.marker"
